import Component from 'flarum/common/Component';
import AutocompleteDropdown from 'flarum/common/components/AutocompleteDropdown';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
/** Waits for a pause in typing, so a search isn't sent per keystroke. */
const DEBOUNCE_MS = 250;
/**
 * A text input that searches as the member types and makes them pick a result,
 * so columns are always built from something that exists (a real user, a real
 * discussion) rather than a typed username or a pasted id.
 */
export default class DeckSearchField extends Component {
  query = '';
  results = [];
  loading = false;
  timer = null;
  /** Ignores responses to queries the member has since typed past. */
  latest = 0;
  onremove(vnode) {
    super.onremove(vnode);
    if (this.timer) clearTimeout(this.timer);
  }
  view() {
    const {
      search,
      placeholder,
      id
    } = this.attrs;
    return m(DeckSearchSuggestions, {
      query: this.query,
      onchange: value => this.input(value),
      suggestions: this.results.map((result, i) => m("li", {
        "data-index": i
      }, m("button", {
        type: "button",
        onclick: () => this.pick(result)
      }, search.display(result, this.query))))
    }, m("input", {
      id: id,
      className: "FormControl",
      type: "search",
      autocomplete: "off",
      placeholder: placeholder,
      value: this.query,
      oninput: e => this.input(e.target.value)
    }), this.loading && m(LoadingIndicator, {
      size: "small",
      display: "inline",
      className: "DeckSearchField-loading"
    }));
  }
  input(value) {
    const {
      search,
      onpick
    } = this.attrs;
    this.query = value;
    this.results = [];
    onpick(null);
    if (this.timer) clearTimeout(this.timer);
    if (value.trim().length < (search.minLength ?? 2)) {
      this.loading = false;
      return;
    }
    this.loading = true;
    this.timer = window.setTimeout(() => {
      const request = ++this.latest;
      search.find(value.trim()).then(results => {
        if (request === this.latest) this.results = results;
      }).catch(() => {}).finally(() => {
        if (request === this.latest) this.loading = false;
        m.redraw();
      });
    }, DEBOUNCE_MS);
  }
  pick(result) {
    this.query = this.attrs.search.label(result);
    this.results = [];
    this.attrs.onpick(this.attrs.search.params(result));
  }
}
/** Core's autocomplete, for keyboard navigation and the suggestion list styling. */
class DeckSearchSuggestions extends AutocompleteDropdown {
  suggestions() {
    return this.attrs.suggestions;
  }
  selectSuggestion() {
    // Enter with nothing suggested yet does nothing, rather than throwing.
    if (this.selectableItems().length) super.selectSuggestion();
  }

  // The modal's content scrolls; the window-based height cap would clip it.
  updateMaxHeight() {}
}
flarum.reg.add('flarum-deck', 'forum/components/DeckSearchField', DeckSearchField);